package com.superglassplanner;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

import static com.superglassplanner.SuperglassConstants.*;

/**
 * Scans the player's bank and rune pouch for Superglass Make materials.
 */
@Slf4j
@Singleton
public class BankScanner
{
	// Rune pouch varbits (supports up to 6 slots with divine rune pouch)
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {29, 1622, 1623, 4726, 4727, 4728};
	private static final int[] RUNE_POUCH_AMOUNT_VARBITS = {1624, 1625, 1626, 4729, 4730, 4731};
	// Rune pouch type ID for astral rune (from RuneLite's runepouch enum)
	private static final int RUNE_POUCH_ASTRAL_TYPE = 14;

	private static final int LOOTING_BAG_CONTAINER_ID = 516;

	@Inject
	private Client client;

	@Getter
	private int giantSeaweedCount;

	@Getter
	private int bucketOfSandCount;

	@Getter
	private int moltenGlassCount;

	@Getter
	private int astralRuneCount;

	@Getter
	private int runePouchAstralCount;

	@Getter
	private int lootingBagGlassCount;

	private int inventoryGlassCount;
	private int inventorySeaweedCount;
	private int inventorySandCount;
	private int inventoryAstralCount;

	@Getter
	private boolean bankLoaded;

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();

		if (containerId == InventoryID.BANK.getId())
		{
			updateBankCounts(event.getItemContainer());
			updateRunePouchCounts();
		}
		else if (containerId == LOOTING_BAG_CONTAINER_ID)
		{
			updateLootingBagCounts(event.getItemContainer());
		}
		else if (containerId == InventoryID.INVENTORY.getId())
		{
			updateInventoryCounts(event.getItemContainer());
		}
	}

	private void updateBankCounts(ItemContainer bank)
	{
		if (bank == null)
		{
			return;
		}

		giantSeaweedCount = 0;
		bucketOfSandCount = 0;
		moltenGlassCount = 0;
		astralRuneCount = 0;

		for (Item item : bank.getItems())
		{
			if (item == null)
			{
				continue;
			}

			switch (item.getId())
			{
				case GIANT_SEAWEED:
					giantSeaweedCount += item.getQuantity();
					break;
				case BUCKET_OF_SAND:
					bucketOfSandCount += item.getQuantity();
					break;
				case MOLTEN_GLASS:
					moltenGlassCount += item.getQuantity();
					break;
				case ASTRAL_RUNE:
					astralRuneCount += item.getQuantity();
					break;
			}
		}

		bankLoaded = true;
		log.debug("Bank scanned - Seaweed: {}, Sand: {}, Glass: {}, Astrals: {}",
			giantSeaweedCount, bucketOfSandCount, moltenGlassCount, astralRuneCount);
	}

	private void updateLootingBagCounts(ItemContainer bag)
	{
		lootingBagGlassCount = 0;
		if (bag == null)
		{
			return;
		}
		for (Item item : bag.getItems())
		{
			if (item != null && item.getId() == MOLTEN_GLASS)
			{
				lootingBagGlassCount += item.getQuantity();
			}
		}
		log.debug("Looting bag glass: {}", lootingBagGlassCount);
	}

	private void updateInventoryCounts(ItemContainer inventory)
	{
		inventoryGlassCount = 0;
		inventorySeaweedCount = 0;
		inventorySandCount = 0;
		inventoryAstralCount = 0;
		if (inventory == null)
		{
			return;
		}
		for (Item item : inventory.getItems())
		{
			if (item == null) continue;
			switch (item.getId())
			{
				case MOLTEN_GLASS:
					inventoryGlassCount += item.getQuantity();
					break;
				case GIANT_SEAWEED:
					inventorySeaweedCount += item.getQuantity();
					break;
				case BUCKET_OF_SAND:
					inventorySandCount += item.getQuantity();
					break;
				case ASTRAL_RUNE:
					inventoryAstralCount += item.getQuantity();
					break;
			}
		}
	}

	/**
	 * Total molten glass across bank + looting bag + inventory.
	 */
	public int totalMoltenGlass()
	{
		return moltenGlassCount + lootingBagGlassCount + inventoryGlassCount;
	}

	/**
	 * Molten glass in inventory + looting bag only (excludes bank).
	 */
	public int nonBankMoltenGlass()
	{
		return lootingBagGlassCount + inventoryGlassCount;
	}

	/**
	 * Reads astral rune count from the rune pouch via varbits.
	 */
	private void updateRunePouchCounts()
	{
		runePouchAstralCount = 0;

		for (int i = 0; i < RUNE_POUCH_TYPE_VARBITS.length; i++)
		{
			int runeType = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			int amount = client.getVarbitValue(RUNE_POUCH_AMOUNT_VARBITS[i]);

			if (runeType == RUNE_POUCH_ASTRAL_TYPE && amount > 0)
			{
				runePouchAstralCount += amount;
			}
		}

		log.debug("Rune pouch astrals: {}", runePouchAstralCount);
	}

	/**
	 * Total giant seaweed across bank + inventory.
	 */
	public int totalGiantSeaweed()
	{
		return giantSeaweedCount + inventorySeaweedCount;
	}

	/**
	 * Total buckets of sand across bank + inventory.
	 */
	public int totalBucketOfSand()
	{
		return bucketOfSandCount + inventorySandCount;
	}

	/**
	 * Total astral runes across bank + rune pouch + inventory.
	 */
	public int totalAstralRunes()
	{
		return astralRuneCount + runePouchAstralCount + inventoryAstralCount;
	}

	/**
	 * Returns how many Superglass Make casts are possible with current materials.
	 * Factors in giant seaweed, sand, AND astral runes (2 per cast).
	 */
	public int possibleCasts()
	{
		int castsBySeaweed = totalGiantSeaweed() / GIANT_SEAWEED_PER_CAST;
		int castsBySand = totalBucketOfSand() / SAND_PER_CAST;
		int castsByAstrals = totalAstralRunes() / ASTRAL_RUNES_PER_CAST;
		return Math.min(castsBySeaweed, Math.min(castsBySand, castsByAstrals));
	}

	/**
	 * Returns estimated molten glass from current materials.
	 */
	public int estimatedGlass(double glassPerCast)
	{
		return (int) (possibleCasts() * glassPerCast);
	}

	/**
	 * Calculates the max casts if you had unlimited of this resource,
	 * i.e. the max casts based on the OTHER two resources.
	 */
	public int maxCastsIgnoringSeaweed()
	{
		int castsBySand = totalBucketOfSand() / SAND_PER_CAST;
		int castsByAstrals = totalAstralRunes() / ASTRAL_RUNES_PER_CAST;
		return Math.min(castsBySand, castsByAstrals);
	}

	public int maxCastsIgnoringSand()
	{
		int castsBySeaweed = totalGiantSeaweed() / GIANT_SEAWEED_PER_CAST;
		int castsByAstrals = totalAstralRunes() / ASTRAL_RUNES_PER_CAST;
		return Math.min(castsBySeaweed, castsByAstrals);
	}

	public int maxCastsIgnoringAstrals()
	{
		int castsBySeaweed = totalGiantSeaweed() / GIANT_SEAWEED_PER_CAST;
		int castsBySand = totalBucketOfSand() / SAND_PER_CAST;
		return Math.min(castsBySeaweed, castsBySand);
	}

	/**
	 * How much more seaweed you need to fully use your sand + astrals.
	 */
	public int seaweedDeficit()
	{
		int needed = maxCastsIgnoringSeaweed() * GIANT_SEAWEED_PER_CAST;
		return Math.max(0, needed - totalGiantSeaweed());
	}

	/**
	 * How much more sand you need to fully use your seaweed + astrals.
	 */
	public int sandDeficit()
	{
		int needed = maxCastsIgnoringSand() * SAND_PER_CAST;
		return Math.max(0, needed - totalBucketOfSand());
	}

	/**
	 * How many more astrals you need to fully use your seaweed + sand.
	 */
	public int astralDeficit()
	{
		int needed = maxCastsIgnoringAstrals() * ASTRAL_RUNES_PER_CAST;
		return Math.max(0, needed - totalAstralRunes());
	}

	// Perspective-based: "to use all of X, how much more Y do I need?"

	public int castsFromSeaweed()
	{
		return totalGiantSeaweed() / GIANT_SEAWEED_PER_CAST;
	}

	public int castsFromSand()
	{
		return totalBucketOfSand() / SAND_PER_CAST;
	}

	public int castsFromAstrals()
	{
		return totalAstralRunes() / ASTRAL_RUNES_PER_CAST;
	}

	public int sandNeededForCasts(int casts)
	{
		return Math.max(0, casts * SAND_PER_CAST - totalBucketOfSand());
	}

	public int seaweedNeededForCasts(int casts)
	{
		return Math.max(0, casts * GIANT_SEAWEED_PER_CAST - totalGiantSeaweed());
	}

	public int astralsNeededForCasts(int casts)
	{
		return Math.max(0, casts * ASTRAL_RUNES_PER_CAST - totalAstralRunes());
	}

	public void reset()
	{
		giantSeaweedCount = 0;
		bucketOfSandCount = 0;
		moltenGlassCount = 0;
		astralRuneCount = 0;
		runePouchAstralCount = 0;
		lootingBagGlassCount = 0;
		inventoryGlassCount = 0;
		inventorySeaweedCount = 0;
		inventorySandCount = 0;
		inventoryAstralCount = 0;
		bankLoaded = false;
	}
}

package com.superglassplanner;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Glass items that can be blown from molten glass, with their Crafting XP and level requirements.
 */
@Getter
@RequiredArgsConstructor
public enum GlassItem
{
	BEST_AVAILABLE("Best available", 0, 0),
	BEER_GLASS("Beer glass", 17.5, 1),
	CANDLE_LANTERN("Empty candle lantern", 19.0, 4),
	OIL_LAMP("Empty oil lamp", 25.0, 12),
	VIAL("Vial", 35.0, 33),
	FISHBOWL("Empty fishbowl", 42.5, 42),
	UNPOWERED_ORB("Unpowered orb", 52.5, 46),
	LANTERN_LENS("Lantern lens", 55.0, 49),
	LIGHT_ORB("Light orb", 70.0, 87);

	private final String displayName;
	private final double xpPerGlass;
	private final int levelRequired;

	/**
	 * Returns the highest-XP glass item available at the given crafting level.
	 */
	public static GlassItem bestItemForLevel(int level)
	{
		GlassItem best = BEER_GLASS;
		for (GlassItem item : values())
		{
			if (item == BEST_AVAILABLE) continue;
			if (item.levelRequired <= level && item.xpPerGlass > best.xpPerGlass)
			{
				best = item;
			}
		}
		return best;
	}

	@Override
	public String toString()
	{
		if (this == BEST_AVAILABLE) return displayName;
		return displayName + " (" + xpPerGlass + " xp)";
	}
}

package com.superglassplanner;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;
import java.text.NumberFormat;

/**
 * Compact overlay showing glassblowing session stats.
 */
public class GlassblowingOverlay extends OverlayPanel
{
	private final SuperglassPlannerConfig config;
	private final GlassblowingTracker tracker;
	private final GoalCalculator goalCalculator;

	private static final NumberFormat FORMAT = NumberFormat.getIntegerInstance();

	@Inject
	public GlassblowingOverlay(
		SuperglassPlannerConfig config,
		GlassblowingTracker tracker,
		GoalCalculator goalCalculator)
	{
		this.config = config;
		this.tracker = tracker;
		this.goalCalculator = goalCalculator;

		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(OverlayPriority.LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showGlassblowingOverlay() || tracker.getItemsBlown() == 0)
		{
			return null;
		}

		int timeoutMinutes = config.glassblowingTimeout();
		if (timeoutMinutes > 0 && tracker.getLastBlowMillis() > 0)
		{
			long elapsed = System.currentTimeMillis() - tracker.getLastBlowMillis();
			if (elapsed > timeoutMinutes * 60_000L)
			{
				return null;
			}
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Glassblowing")
			.color(new Color(255, 152, 0))
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Items Blown:")
			.right(FORMAT.format(tracker.getItemsBlown()))
			.build());

		if (config.glassblowingItemsToGoal())
		{
			int toGoal = config.glassblowingFactorMakeXp()
				? goalCalculator.totalItemsToBlow()
				: goalCalculator.itemsToBlowForGoal();
			if (toGoal > 0)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Items to Goal:")
					.right(FORMAT.format(toGoal))
					.build());
			}
		}
		else
		{
			int toLevel = goalCalculator.itemsToBlowForLevel();
			if (toLevel > 0)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Items to Level:")
					.right(FORMAT.format(toLevel))
					.build());
			}
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Crafting XP:")
			.right(FORMAT.format(tracker.getCraftingXpGained()))
			.build());

		return super.render(graphics);
	}
}

package com.superglassplanner;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

import static com.superglassplanner.SuperglassConstants.*;

/**
 * Tracks glassblowing session statistics (blowing molten glass into items).
 */
@Slf4j
@Singleton
public class GlassblowingTracker
{
	@Inject
	private Client client;

	@Getter
	private int itemsBlown;

	@Getter
	private long lastBlowMillis;

	@Getter
	private int craftingXpGained;

	private int lastCraftingXp = -1;
	private int lastInventoryGlassCount = -1;
	private boolean blowing = false;

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() != client.getLocalPlayer())
		{
			return;
		}

		if (event.getActor().getAnimation() == GLASSBLOWING_ANIMATION)
		{
			blowing = true;
			lastBlowMillis = System.currentTimeMillis();
		}
		else
		{
			blowing = false;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INVENTORY.getId())
		{
			return;
		}

		int currentGlass = countItem(event.getItemContainer(), MOLTEN_GLASS);
		if (blowing && lastInventoryGlassCount >= 0)
		{
			int delta = lastInventoryGlassCount - currentGlass;
			if (delta > 0)
			{
				itemsBlown += delta;
				log.debug("Glass blown: +{}, total items: {}", delta, itemsBlown);
			}
		}
		lastInventoryGlassCount = currentGlass;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.CRAFTING)
		{
			return;
		}

		int currentXp = event.getXp();
		if (lastCraftingXp >= 0 && itemsBlown > 0)
		{
			int gained = currentXp - lastCraftingXp;
			if (gained > 0)
			{
				craftingXpGained += gained;
			}
		}
		lastCraftingXp = currentXp;
	}

	private int countItem(ItemContainer container, int itemId)
	{
		int count = 0;
		if (container == null)
		{
			return count;
		}
		for (Item item : container.getItems())
		{
			if (item != null && item.getId() == itemId)
			{
				count += item.getQuantity();
			}
		}
		return count;
	}

	public int getGlassRemaining()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
		return inv != null ? countItem(inv, MOLTEN_GLASS) : 0;
	}

	/**
	 * Resets only transient detection state so tracking resumes
	 * correctly after logout without losing accumulated stats.
	 */
	public void softReset()
	{
		lastCraftingXp = -1;
		lastInventoryGlassCount = -1;
		blowing = false;
	}

	public void reset()
	{
		itemsBlown = 0;
		lastBlowMillis = 0;
		craftingXpGained = 0;
		lastCraftingXp = -1;
		lastInventoryGlassCount = -1;
		blowing = false;
	}
}

package com.superglassplanner;

import net.runelite.api.Client;
import net.runelite.api.Skill;

import javax.inject.Inject;
import javax.inject.Singleton;

import static com.superglassplanner.SuperglassConstants.*;

/**
 * Calculates materials needed to reach a crafting goal via Superglass Make.
 */
@Singleton
public class GoalCalculator
{
	@Inject
	private Client client;

	@Inject
	private SuperglassPlannerConfig config;

	@Inject
	private BankScanner bankScanner;

	/**
	 * Glass per cast based on config: when picking up extra glass, uses the
	 * statistical average (28.8); otherwise, uses the user-configured value
	 * which depends on free inventory slots.
	 */
	public double glassPerCast()
	{
		return config.pickupExtraGlass() ? AVG_TOTAL_GLASS_PER_CAST : Math.max(1, config.glassPerCast());
	}

	/**
	 * The glass item to use for calculations at the player's current level.
	 * Resolves BEST_AVAILABLE to the actual best item.
	 */
	public GlassItem currentGlassItem()
	{
		GlassItem item = config.glassItem();
		if (item == GlassItem.BEST_AVAILABLE)
		{
			return GlassItem.bestItemForLevel(client.getRealSkillLevel(Skill.CRAFTING));
		}
		return item;
	}

	private double makeXpPerGlass()
	{
		return CRAFTING_XP_PER_CAST / glassPerCast();
	}

	/**
	 * Effective crafting XP per glass, including both Superglass Make cast XP
	 * and the XP from blowing the glass item. Uses current level's best item
	 * when BEST_AVAILABLE is selected.
	 */
	public double effectiveXpPerGlass()
	{
		return currentGlassItem().getXpPerGlass() + makeXpPerGlass();
	}

	private double effectiveXpPerGlass(GlassItem item)
	{
		return item.getXpPerGlass() + makeXpPerGlass();
	}

	/**
	 * XP remaining to reach goal.
	 */
	public int xpRemaining()
	{
		int currentXp = client.getSkillExperience(Skill.CRAFTING);
		int targetXp;

		switch (config.goalType())
		{
			case TARGET_LEVEL:
				targetXp = xpForLevel(config.targetLevel());
				break;
			case TARGET_XP:
				targetXp = config.targetXp();
				break;
			case TARGET_GLASS:
				targetXp = currentXp + (int) (config.targetGlass() * effectiveXpPerGlass());
				break;
			default:
				targetXp = xpForLevel(99);
		}

		return Math.max(0, targetXp - currentXp);
	}

	/**
	 * Molten glass needed to reach goal.
	 */
	public int glassNeeded()
	{
		if (config.goalType() == GoalType.TARGET_GLASS)
		{
			int needed = config.targetGlass();
			if (config.factorExistingGlass())
			{
				needed = Math.max(0, needed - bankScanner.totalMoltenGlass());
			}
			return needed;
		}

		int remaining = xpRemaining();

		if (config.factorExistingGlass())
		{
			int existingGlass = bankScanner.totalMoltenGlass();
			double xpFromExisting = existingGlass * currentGlassItem().getXpPerGlass();
			remaining = Math.max(0, (int) (remaining - xpFromExisting));
		}

		if (config.glassItem() == GlassItem.BEST_AVAILABLE)
		{
			return glassNeededBestAvailable(remaining);
		}

		return (int) Math.ceil(remaining / effectiveXpPerGlass());
	}

	/**
	 * Walks level brackets to calculate glass needed when making the best
	 * available item at each crafting level.
	 */
	private int glassNeededBestAvailable(int xpRemaining)
	{
		if (xpRemaining <= 0) return 0;

		double xpLeft = xpRemaining;
		double currentXp = client.getSkillExperience(Skill.CRAFTING);
		double mxpg = makeXpPerGlass();
		int totalGlass = 0;

		while (xpLeft > 0)
		{
			int level = levelAtXp((int) currentXp);
			GlassItem best = GlassItem.bestItemForLevel(level);
			double effXp = best.getXpPerGlass() + mxpg;

			// Find the XP threshold where the next better item unlocks
			double bracketCeiling = xpLeft;
			for (GlassItem candidate : GlassItem.values())
			{
				if (candidate == GlassItem.BEST_AVAILABLE) continue;
				if (candidate.getLevelRequired() > level)
				{
					double xpToUnlock = xpForLevel(candidate.getLevelRequired()) - currentXp;
					if (xpToUnlock > 0 && xpToUnlock < bracketCeiling)
					{
						bracketCeiling = xpToUnlock;
					}
				}
			}

			int glassInBracket = (int) Math.ceil(bracketCeiling / effXp);
			double xpFromBracket = glassInBracket * effXp;
			totalGlass += glassInBracket;
			xpLeft -= xpFromBracket;
			currentXp += xpFromBracket;
		}

		return totalGlass;
	}

	/**
	 * Returns the crafting level at a given XP amount.
	 */
	private int levelAtXp(int xp)
	{
		for (int level = 99; level >= 1; level--)
		{
			if (xp >= xpForLevel(level))
			{
				return level;
			}
		}
		return 1;
	}

	/**
	 * Superglass Make casts needed.
	 */
	public int castsNeeded()
	{
		return (int) Math.ceil(glassNeeded() / glassPerCast());
	}

	/**
	 * Items to blow to reach goal using only blow XP (for overlay during active blowing).
	 */
	public int itemsToBlowForGoal()
	{
		double xpPerItem = currentGlassItem().getXpPerGlass();
		if (xpPerItem <= 0) return 0;
		return (int) Math.ceil(xpRemaining() / xpPerItem);
	}

	/**
	 * Items to blow to reach the next crafting level using only blow XP.
	 */
	public int itemsToBlowForLevel()
	{
		double xpPerItem = currentGlassItem().getXpPerGlass();
		if (xpPerItem <= 0) return 0;
		int currentLevel = client.getRealSkillLevel(Skill.CRAFTING);
		if (currentLevel >= 99) return 0;
		int currentXp = client.getSkillExperience(Skill.CRAFTING);
		int nextLevelXp = xpForLevel(currentLevel + 1);
		int remaining = Math.max(0, nextLevelXp - currentXp);
		return (int) Math.ceil(remaining / xpPerItem);
	}

	/**
	 * Total items to blow to reach goal, factoring in Superglass Make XP.
	 * When "factor existing glass" is on, includes existing glass that still needs blowing.
	 */
	public int totalItemsToBlow()
	{
		if (config.factorExistingGlass())
		{
			int existingGlass = bankScanner.totalMoltenGlass();
			return glassNeeded() + existingGlass;
		}
		return glassNeeded();
	}

	/**
	 * Giant seaweed needed.
	 */
	public int seaweedNeeded()
	{
		return castsNeeded() * GIANT_SEAWEED_PER_CAST;
	}

	/**
	 * Buckets of sand needed.
	 */
	public int sandNeeded()
	{
		return castsNeeded() * SAND_PER_CAST;
	}

	/**
	 * Seaweed still needed after accounting for bank.
	 */
	public int seaweedDeficit()
	{
		return Math.max(0, seaweedNeeded() - bankScanner.totalGiantSeaweed());
	}

	/**
	 * Sand still needed after accounting for bank.
	 */
	public int sandDeficit()
	{
		return Math.max(0, sandNeeded() - bankScanner.totalBucketOfSand());
	}

	/**
	 * Progress percentage toward goal (0.0 to 1.0).
	 */
	public double progress()
	{
		int currentXp = client.getSkillExperience(Skill.CRAFTING);

		switch (config.goalType())
		{
			case TARGET_LEVEL:
			{
				int startXp = xpForLevel(client.getRealSkillLevel(Skill.CRAFTING));
				int targetXp = xpForLevel(config.targetLevel());
				if (targetXp <= startXp) return 1.0;
				return (double) (currentXp - startXp) / (targetXp - startXp);
			}
			case TARGET_XP:
			{
				int startXp = xpForLevel(client.getRealSkillLevel(Skill.CRAFTING));
				int targetXp = config.targetXp();
				if (targetXp <= currentXp) return 1.0;
				return (double) (currentXp - startXp) / (targetXp - startXp);
			}
			case TARGET_GLASS:
			default:
				return 0.0;
		}
	}

	/**
	 * Human-readable goal description for the panel header.
	 */
	public String goalDescription()
	{
		switch (config.goalType())
		{
			case TARGET_LEVEL:
				return "Level " + config.targetLevel();
			case TARGET_XP:
				return config.targetXp() + " XP";
			case TARGET_GLASS:
				return config.targetGlass() + " glass";
			default:
				return "Goal";
		}
	}
}

